    (id=12, name=:N1nu_AA, initial=(:N1, :nu), final=(:A, :A), resonance=:phi, msq=msq_N1nu_AA, xyz=xyz_N1nu_AA),
    (id=13, name=:N2nu_Aphi, initial=(:N2, :nu), final=(:A, :phi), resonance=:A, msq=msq_N2nu_Aphi, xyz=xyz_N2nu_Aphi),
    (id=14, name=:N1nu_phiphi, initial=(:N1, :nu), final=(:phi, :phi), resonance=:phi, msq=msq_N1nu_phiphi, xyz=xyz_N1nu_phiphi),
]

"""sum|M|^2 = X |D|^2 + 2 Y Re D + Z for a Breit-Wigner D = 1/(s - m^2 + i m Gamma)."""
function msq_bw(xyz, s, m, Gamma)
    X, Y, Z = xyz
    d = s - m^2
    den = d^2 + m^2 * Gamma^2
    return X / den + 2 * Y * d / den + Z
end

end # module